-- Forward-only guards; existing learning records are retained.
CREATE TRIGGER curriculum_version_locked_update BEFORE UPDATE ON curriculum_versions WHEN OLD.status <> 'draft' BEGIN SELECT RAISE(ABORT,'Active curriculum is immutable'); END;
CREATE TRIGGER curriculum_version_locked_delete BEFORE DELETE ON curriculum_versions WHEN OLD.status <> 'draft' BEGIN SELECT RAISE(ABORT,'Active curriculum is immutable'); END;
CREATE TRIGGER competency_levels_locked_insert BEFORE INSERT ON competency_levels WHEN (SELECT status FROM curriculum_versions WHERE id=NEW.curriculum_version_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER competency_levels_locked_update BEFORE UPDATE ON competency_levels WHEN (SELECT status FROM curriculum_versions WHERE id=OLD.curriculum_version_id) <> 'draft' OR (SELECT status FROM curriculum_versions WHERE id=NEW.curriculum_version_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER competency_levels_locked_delete BEFORE DELETE ON competency_levels WHEN (SELECT status FROM curriculum_versions WHERE id=OLD.curriculum_version_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER competency_packages_locked_insert BEFORE INSERT ON competency_packages WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id WHERE cl.id=NEW.competency_level_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER competency_packages_locked_update BEFORE UPDATE ON competency_packages WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id WHERE cl.id=OLD.competency_level_id) <> 'draft' OR (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id WHERE cl.id=NEW.competency_level_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER competency_packages_locked_delete BEFORE DELETE ON competency_packages WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id WHERE cl.id=OLD.competency_level_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER core_competencies_locked_insert BEFORE INSERT ON core_competencies WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id WHERE cp.id=NEW.competency_package_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER core_competencies_locked_update BEFORE UPDATE ON core_competencies WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id WHERE cp.id=OLD.competency_package_id) <> 'draft' OR (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id WHERE cp.id=NEW.competency_package_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER core_competencies_locked_delete BEFORE DELETE ON core_competencies WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id WHERE cp.id=OLD.competency_package_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER basic_competencies_locked_insert BEFORE INSERT ON basic_competencies WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id JOIN core_competencies ki ON ki.competency_package_id=cp.id WHERE ki.id=NEW.core_competency_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER basic_competencies_locked_update BEFORE UPDATE ON basic_competencies WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id JOIN core_competencies ki ON ki.competency_package_id=cp.id WHERE ki.id=OLD.core_competency_id) <> 'draft' OR (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id JOIN core_competencies ki ON ki.competency_package_id=cp.id WHERE ki.id=NEW.core_competency_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER basic_competencies_locked_delete BEFORE DELETE ON basic_competencies WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id JOIN core_competencies ki ON ki.competency_package_id=cp.id WHERE ki.id=OLD.core_competency_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER subject_skk_allocations_locked_insert BEFORE INSERT ON subject_skk_allocations WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id WHERE cp.id=NEW.competency_package_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER subject_skk_allocations_locked_update BEFORE UPDATE ON subject_skk_allocations WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id WHERE cp.id=OLD.competency_package_id) <> 'draft' OR (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id WHERE cp.id=NEW.competency_package_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER subject_skk_allocations_locked_delete BEFORE DELETE ON subject_skk_allocations WHEN (SELECT v.status FROM curriculum_versions v JOIN competency_levels cl ON cl.curriculum_version_id=v.id JOIN competency_packages cp ON cp.competency_level_id=cl.id WHERE cp.id=OLD.competency_package_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER learning_modes_locked_insert BEFORE INSERT ON learning_modes WHEN (SELECT status FROM curriculum_versions WHERE id=NEW.curriculum_version_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER learning_modes_locked_update BEFORE UPDATE ON learning_modes WHEN (SELECT status FROM curriculum_versions WHERE id=OLD.curriculum_version_id) <> 'draft' OR (SELECT status FROM curriculum_versions WHERE id=NEW.curriculum_version_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER learning_modes_locked_delete BEFORE DELETE ON learning_modes WHEN (SELECT status FROM curriculum_versions WHERE id=OLD.curriculum_version_id) <> 'draft' BEGIN SELECT RAISE(ABORT,'Curriculum mapping is immutable'); END;
CREATE TRIGGER skk_positive_insert BEFORE INSERT ON subject_skk_allocations WHEN NEW.planned_skk <= 0 OR typeof(NEW.planned_skk)<>'integer' OR NEW.face_to_face_percent<0 OR NEW.tutorial_percent<0 OR NEW.independent_percent<0 OR NEW.face_to_face_percent+NEW.tutorial_percent+NEW.independent_percent<>100 BEGIN SELECT RAISE(ABORT,'Invalid SKK or learning modes'); END;
CREATE TRIGGER materials_competency_insert BEFORE INSERT ON materials WHEN NEW.status='published' AND NOT EXISTS(SELECT 1 FROM material_basic_competencies WHERE material_id=NEW.id) BEGIN SELECT RAISE(ABORT,'Publication requires competency'); END;
CREATE TRIGGER materials_competency_update BEFORE UPDATE ON materials WHEN NEW.status='published' AND NOT EXISTS(SELECT 1 FROM material_basic_competencies WHERE material_id=NEW.id) BEGIN SELECT RAISE(ABORT,'Publication requires competency'); END;
CREATE TRIGGER material_basic_competencies_history_delete BEFORE DELETE ON material_basic_competencies WHEN (SELECT status FROM materials WHERE id=OLD.material_id)='published' BEGIN SELECT RAISE(ABORT,'Published competency history is immutable'); END;
CREATE TRIGGER material_basic_competencies_history_update BEFORE UPDATE ON material_basic_competencies WHEN (SELECT status FROM materials WHERE id=OLD.material_id)='published' BEGIN SELECT RAISE(ABORT,'Published competency history is immutable'); END;
CREATE TRIGGER quizzes_competency_insert BEFORE INSERT ON quizzes WHEN NEW.status='published' AND NOT EXISTS(SELECT 1 FROM quiz_basic_competencies WHERE quiz_id=NEW.id) BEGIN SELECT RAISE(ABORT,'Publication requires competency'); END;
CREATE TRIGGER quizzes_competency_update BEFORE UPDATE ON quizzes WHEN NEW.status='published' AND NOT EXISTS(SELECT 1 FROM quiz_basic_competencies WHERE quiz_id=NEW.id) BEGIN SELECT RAISE(ABORT,'Publication requires competency'); END;
CREATE TRIGGER quiz_basic_competencies_history_delete BEFORE DELETE ON quiz_basic_competencies WHEN (SELECT status FROM quizzes WHERE id=OLD.quiz_id)='published' BEGIN SELECT RAISE(ABORT,'Published competency history is immutable'); END;
CREATE TRIGGER quiz_basic_competencies_history_update BEFORE UPDATE ON quiz_basic_competencies WHEN (SELECT status FROM quizzes WHERE id=OLD.quiz_id)='published' BEGIN SELECT RAISE(ABORT,'Published competency history is immutable'); END;
CREATE TRIGGER assignments_competency_insert BEFORE INSERT ON assignments WHEN NEW.status='published' AND NOT EXISTS(SELECT 1 FROM assignment_basic_competencies WHERE assignment_id=NEW.id) BEGIN SELECT RAISE(ABORT,'Publication requires competency'); END;
CREATE TRIGGER assignments_competency_update BEFORE UPDATE ON assignments WHEN NEW.status='published' AND NOT EXISTS(SELECT 1 FROM assignment_basic_competencies WHERE assignment_id=NEW.id) BEGIN SELECT RAISE(ABORT,'Publication requires competency'); END;
CREATE TRIGGER assignment_basic_competencies_history_delete BEFORE DELETE ON assignment_basic_competencies WHEN (SELECT status FROM assignments WHERE id=OLD.assignment_id)='published' BEGIN SELECT RAISE(ABORT,'Published competency history is immutable'); END;
CREATE TRIGGER assignment_basic_competencies_history_update BEFORE UPDATE ON assignment_basic_competencies WHEN (SELECT status FROM assignments WHERE id=OLD.assignment_id)='published' BEGIN SELECT RAISE(ABORT,'Published competency history is immutable'); END;
CREATE TRIGGER assignment_version_consistency BEFORE INSERT ON curriculum_assignments WHEN NOT EXISTS(SELECT 1 FROM competency_packages cp JOIN competency_levels cl ON cl.id=cp.competency_level_id JOIN curriculum_versions v ON v.id=cl.curriculum_version_id JOIN class_memberships cm ON cm.class_id=v.class_id WHERE cp.id=NEW.competency_package_id AND v.id=NEW.curriculum_version_id AND v.class_id=NEW.class_id AND v.status='active' AND cm.student_id=NEW.student_id AND cm.status='active') BEGIN SELECT RAISE(ABORT,'Invalid curriculum assignment'); END;
